/**
 * The shape of the pinned Blood Death Knight aura-duration artifact, and a
 * runtime validator for it (M11-B4).
 *
 * Generated by `scripts/authority/extract-simc-blood-aura-durations.mjs` from
 * one exact SimulationCraft commit and committed. Nothing here reaches the
 * network.
 *
 * WHAT THIS DATA IS FOR
 *
 * The pinned Blood lists ask `buff.bone_shield.remains<1.5`,
 * `buff.essence_of_the_blood_queen.remains<8`, and read three more auras'
 * remainders as bare truths. Warcraft Logs reports that an aura was APPLIED,
 * REFRESHED or REMOVED at a time — never how long it had left. Turning the one
 * into the other needs the aura's duration AS SIMULATIONCRAFT RESOLVES IT and
 * the refresh semantics the engine applies, which are game facts and so belong
 * in runtime data with provenance.
 *
 * WHAT `finalDurationMs` IS
 *
 * `spell_data_t::_duration` (DBC milliseconds) plus every duration modifier
 * from an unconditional Blood specialization passive — the value
 * `buff_t::set_duration` reads through `get_passive_value( data(), "duration" )`
 * at the pinned commit. Essence of the Blood Queen is 20,000 + 5,000. A
 * modifier from any other source (a talent) is build-dependent, and an aura
 * carrying one is NOT in this artifact: the extractor refuses it rather than
 * choosing a build.
 *
 * THE TWO REMAINS MODELS, AND THE VALIDATOR'S REFUSAL OF ANY OTHER
 *
 *     FIXED_DURATION_RESET_ON_GAIN   an application starts the full duration;
 *                                    every later trigger (a stack gain, a
 *                                    refresh) reschedules the expiry to the
 *                                    FULL duration; a stack loss leaves it
 *                                    alone; a removal ends it
 *     PERMANENT                      no expiration is ever scheduled; while
 *                                    active SimulationCraft reports
 *                                    `timespan_t::min()`
 *
 * PANDEMIC, EXTEND, TICK, MAX and CUSTOM refresh behaviours exist in the
 * engine and are not admitted here. An artifact naming one fails validation,
 * so a future aura that needs one shows up as a missing model, not as a
 * fixed-duration approximation.
 *
 * UNITS. Every duration field is MILLISECONDS and says so in its name; the
 * artifact records the unit and the validator rejects any other. The single
 * ms -> s conversion lives in the Blood derivation that builds the expression
 * binding.
 */

/** The artifact schema version this build understands. */
export const SUPPORTED_BLOOD_AURA_DURATION_ARTIFACT_VERSION = 1;

/** The only unit string the artifact may claim. */
export const BLOOD_AURA_DURATION_UNITS = "MILLISECONDS";

/** The remains models this build can apply. Nothing else validates. */
export type BloodAuraRemainsModel = "FIXED_DURATION_RESET_ON_GAIN" | "PERMANENT";

export const BLOOD_AURA_REMAINS_MODELS = [
  "FIXED_DURATION_RESET_ON_GAIN",
  "PERMANENT",
] as const satisfies readonly BloodAuraRemainsModel[];

export interface BloodAuraDurationArtifactSource {
  readonly path: string;
  readonly sha256: string;
  readonly byteLength: number;
}

export interface BloodAuraDurationArtifactProvenance {
  readonly repository: string;
  readonly commitSha: string;
  readonly sources: readonly BloodAuraDurationArtifactSource[];
  readonly clientDataWowVersion: string;
  readonly clientDataHotfixDate: string;
  readonly clientDataHotfixBuild: number;
  readonly clientDataHotfixHash: string;
  readonly durationFieldName: string;
  /** Always `MILLISECONDS`. Validated, not merely documented. */
  readonly durationFieldUnits: typeof BLOOD_AURA_DURATION_UNITS;
  readonly extractedOn: string;
  readonly extractorVersion: number;
  /** The `data_enums.hh` enumerators the extractor read, by name. */
  readonly enumerators: Readonly<Record<string, number>>;
  readonly durationSemanticsNote: string;
  readonly remainsModelNote: string;
  readonly applicabilityNote: string;
}

/** One duration modifier the pinned data applies to an aura. */
export interface BloodAuraDurationModifier {
  readonly effectId: number;
  readonly spellId: number;
  readonly spellDisplayNameEn: string | null;
  readonly effectIndex: number;
  readonly effectSubtype: number;
  /** Only flat millisecond modifiers are admitted. */
  readonly kind: "FLAT_MS";
  readonly valueMs: number;
  readonly matchedBy: "CLASS_FLAGS" | "LABEL";
  readonly label: number | null;
  /** Only an unconditional specialization passive is admitted. */
  readonly applicability: "BLOOD_SPECIALIZATION_PASSIVE";
  readonly applicabilityBasis: string;
}

export interface BloodAuraDurationIdentity {
  /** The name after `buff.` in the pinned APL. */
  readonly atomName: string;
  /** The spell id. What a Warcraft Logs aura event carries as `abilityGameID`. */
  readonly abilityGameId: number;
  /** Human-readable only. Never used for matching. */
  readonly displayNameEn: string;
  /** `spell_data_t::_duration`, MILLISECONDS, as the table has it (may be negative: the no-duration sentinel). */
  readonly baseDurationMs: number;
  readonly durationModifiers: readonly BloodAuraDurationModifier[];
  /** The duration SimulationCraft resolves for a Blood actor, MILLISECONDS. Zero for PERMANENT. */
  readonly finalDurationMs: number;
  /** `_max_stack`, recorded for traceability. Not a stack model. */
  readonly maxStack: number;
  /** `_internal_cooldown`, MILLISECONDS, recorded for traceability. */
  readonly internalCooldownMs: number;
  readonly refreshAttributes: {
    readonly refreshExtendsDuration: boolean;
    readonly auraDoesNotRefresh: boolean;
    readonly periodicEffectSubtypes: readonly number[];
  };
  readonly refreshBehavior: "DURATION" | "NONE";
  readonly remainsModel: BloodAuraRemainsModel;
  readonly review: {
    readonly sourcePath: string;
    readonly sourceSha256: string;
    readonly creation: string;
    readonly producers: string;
    readonly consumers: string;
  };
}

export interface BloodAuraDurationArtifact {
  readonly artifactVersion: number;
  readonly datasetId: string;
  readonly artifactRevision: string;
  readonly provenance: BloodAuraDurationArtifactProvenance;
  readonly auras: readonly BloodAuraDurationIdentity[];
}

/**
 * Field names that must NOT appear on an aura entry: each is a per-decision
 * derivation that would become a constant nobody re-checks.
 */
export const FORBIDDEN_DERIVED_AURA_KEYS = [
  "remains",
  "remainsSeconds",
  "finalDurationSeconds",
  "baseDurationSeconds",
  "hastedDurationMs",
  "pandemicWindowMs",
  "expiresAtMs",
] as const;

export type BloodAuraDurationArtifactValidationReason =
  | "NOT_AN_OBJECT"
  | "UNSUPPORTED_ARTIFACT_VERSION"
  | "MALFORMED_PROVENANCE"
  | "UNSUPPORTED_DURATION_UNITS"
  | "MALFORMED_AURAS"
  | "MALFORMED_AURA"
  | "MALFORMED_MODIFIER"
  | "UNSUPPORTED_REMAINS_MODEL"
  | "INCONSISTENT_DURATION"
  | "DUPLICATE_ATOM"
  | "DUPLICATE_ABILITY_ID";

export type BloodAuraDurationArtifactValidation =
  | { readonly ok: true; readonly artifact: BloodAuraDurationArtifact }
  | {
      readonly ok: false;
      readonly reason: BloodAuraDurationArtifactValidationReason;
      readonly detail: string;
    };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function str(record: Record<string, unknown>, key: string): string | null {
  const value = record[key];
  return typeof value === "string" && value.length > 0 ? value : null;
}

function int(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isSafeInteger(value) ? value : null;
}

function nonNegativeInt(record: Record<string, unknown>, key: string): number | null {
  const value = int(record, key);
  return value !== null && value >= 0 ? value : null;
}

function invalid(
  reason: BloodAuraDurationArtifactValidationReason,
  detail: string,
): BloodAuraDurationArtifactValidation {
  return { ok: false, reason, detail };
}

function validateSources(value: unknown): readonly BloodAuraDurationArtifactSource[] | null {
  if (!Array.isArray(value) || value.length === 0) return null;
  const sources: BloodAuraDurationArtifactSource[] = [];
  for (const raw of value) {
    if (!isRecord(raw)) return null;
    const path = str(raw, "path");
    const sha256 = str(raw, "sha256");
    const byteLength = int(raw, "byteLength");
    if (path === null || sha256 === null || byteLength === null || byteLength <= 0) return null;
    if (!/^[0-9a-f]{64}$/.test(sha256)) return null;
    sources.push({ path, sha256, byteLength });
  }
  return sources;
}

function validateProvenance(value: unknown): BloodAuraDurationArtifactProvenance | "BAD_UNITS" | null {
  if (!isRecord(value)) return null;
  const repository = str(value, "repository");
  const commitSha = str(value, "commitSha");
  const clientDataWowVersion = str(value, "clientDataWowVersion");
  const clientDataHotfixDate = str(value, "clientDataHotfixDate");
  const clientDataHotfixHash = str(value, "clientDataHotfixHash");
  const durationFieldName = str(value, "durationFieldName");
  const extractedOn = str(value, "extractedOn");
  const durationSemanticsNote = str(value, "durationSemanticsNote");
  const remainsModelNote = str(value, "remainsModelNote");
  const applicabilityNote = str(value, "applicabilityNote");
  const clientDataHotfixBuild = int(value, "clientDataHotfixBuild");
  const extractorVersion = int(value, "extractorVersion");
  const sources = validateSources(value["sources"]);
  const enumerators = value["enumerators"];
  if (
    repository === null ||
    commitSha === null ||
    !/^[0-9a-f]{40}$/.test(commitSha) ||
    clientDataWowVersion === null ||
    clientDataHotfixDate === null ||
    clientDataHotfixHash === null ||
    durationFieldName !== "_duration" ||
    extractedOn === null ||
    durationSemanticsNote === null ||
    remainsModelNote === null ||
    applicabilityNote === null ||
    clientDataHotfixBuild === null ||
    extractorVersion === null ||
    sources === null ||
    !isRecord(enumerators) ||
    Object.values(enumerators).some((entry) => typeof entry !== "number" || !Number.isSafeInteger(entry))
  ) {
    return null;
  }
  if (value["durationFieldUnits"] !== BLOOD_AURA_DURATION_UNITS) return "BAD_UNITS";
  return {
    repository,
    commitSha,
    sources,
    clientDataWowVersion,
    clientDataHotfixDate,
    clientDataHotfixBuild,
    clientDataHotfixHash,
    durationFieldName,
    durationFieldUnits: BLOOD_AURA_DURATION_UNITS,
    extractedOn,
    extractorVersion,
    enumerators: enumerators as Readonly<Record<string, number>>,
    durationSemanticsNote,
    remainsModelNote,
    applicabilityNote,
  };
}

function validateModifier(value: unknown): BloodAuraDurationModifier | null {
  if (!isRecord(value)) return null;
  const effectId = int(value, "effectId");
  const spellId = int(value, "spellId");
  const effectIndex = int(value, "effectIndex");
  const effectSubtype = int(value, "effectSubtype");
  const valueMs = int(value, "valueMs");
  const applicabilityBasis = str(value, "applicabilityBasis");
  const spellDisplayNameEn = value["spellDisplayNameEn"];
  const label = value["label"];
  if (
    effectId === null ||
    spellId === null ||
    effectIndex === null ||
    effectSubtype === null ||
    valueMs === null ||
    applicabilityBasis === null ||
    value["kind"] !== "FLAT_MS" ||
    value["applicability"] !== "BLOOD_SPECIALIZATION_PASSIVE" ||
    (value["matchedBy"] !== "CLASS_FLAGS" && value["matchedBy"] !== "LABEL") ||
    (spellDisplayNameEn !== null && typeof spellDisplayNameEn !== "string") ||
    (label !== null && (typeof label !== "number" || !Number.isSafeInteger(label)))
  ) {
    return null;
  }
  return {
    effectId,
    spellId,
    spellDisplayNameEn,
    effectIndex,
    effectSubtype,
    kind: "FLAT_MS",
    valueMs,
    matchedBy: value["matchedBy"],
    label,
    applicability: "BLOOD_SPECIALIZATION_PASSIVE",
    applicabilityBasis,
  };
}

function validateAura(value: unknown): BloodAuraDurationIdentity | BloodAuraDurationArtifactValidation {
  if (!isRecord(value)) return invalid("MALFORMED_AURA", "an aura entry is not an object");
  const atomName = str(value, "atomName");
  const abilityGameId = int(value, "abilityGameId");
  const displayNameEn = str(value, "displayNameEn");
  const baseDurationMs = int(value, "baseDurationMs");
  const finalDurationMs = nonNegativeInt(value, "finalDurationMs");
  const maxStack = nonNegativeInt(value, "maxStack");
  const internalCooldownMs = nonNegativeInt(value, "internalCooldownMs");
  const refreshAttributes = value["refreshAttributes"];
  const review = value["review"];
  const label = atomName ?? "<unnamed>";
  if (
    atomName === null ||
    !/^[a-z][a-z0-9_]*$/.test(atomName) ||
    abilityGameId === null ||
    abilityGameId <= 0 ||
    displayNameEn === null ||
    baseDurationMs === null ||
    finalDurationMs === null ||
    maxStack === null ||
    internalCooldownMs === null
  ) {
    return invalid("MALFORMED_AURA", `aura '${label}' is missing a required scalar field`);
  }
  for (const key of FORBIDDEN_DERIVED_AURA_KEYS) {
    if (key in value)
      return invalid("MALFORMED_AURA", `aura '${label}' carries forbidden derived field '${key}'`);
  }
  if (
    !isRecord(refreshAttributes) ||
    typeof refreshAttributes["refreshExtendsDuration"] !== "boolean" ||
    typeof refreshAttributes["auraDoesNotRefresh"] !== "boolean" ||
    !Array.isArray(refreshAttributes["periodicEffectSubtypes"]) ||
    refreshAttributes["periodicEffectSubtypes"].some((entry) => typeof entry !== "number")
  ) {
    return invalid("MALFORMED_AURA", `aura '${label}' has malformed refreshAttributes`);
  }
  if (
    !isRecord(review) ||
    str(review, "sourcePath") === null ||
    str(review, "sourceSha256") === null ||
    !/^[0-9a-f]{64}$/.test(str(review, "sourceSha256") ?? "") ||
    str(review, "creation") === null ||
    str(review, "producers") === null ||
    str(review, "consumers") === null
  ) {
    return invalid("MALFORMED_AURA", `aura '${label}' has a malformed review record`);
  }
  const rawModifiers = value["durationModifiers"];
  if (!Array.isArray(rawModifiers)) {
    return invalid("MALFORMED_MODIFIER", `aura '${label}' has no durationModifiers list`);
  }
  const modifiers: BloodAuraDurationModifier[] = [];
  for (const raw of rawModifiers) {
    const modifier = validateModifier(raw);
    if (modifier === null)
      return invalid("MALFORMED_MODIFIER", `aura '${label}' carries a malformed duration modifier`);
    modifiers.push(modifier);
  }
  const remainsModel = value["remainsModel"];
  if (!(BLOOD_AURA_REMAINS_MODELS as readonly unknown[]).includes(remainsModel)) {
    return invalid(
      "UNSUPPORTED_REMAINS_MODEL",
      `aura '${label}' names remains model '${String(remainsModel)}'`,
    );
  }
  const model = remainsModel as BloodAuraRemainsModel;
  const refreshBehavior = value["refreshBehavior"];
  // The model must agree with the facts it was derived from, or the artifact
  // was edited by hand.
  if (model === "PERMANENT") {
    if (baseDurationMs > 0 || finalDurationMs !== 0 || modifiers.length > 0 || refreshBehavior !== "NONE") {
      return invalid("INCONSISTENT_DURATION", `aura '${label}' is PERMANENT but carries a duration`);
    }
  } else {
    const expected = baseDurationMs + modifiers.reduce((sum, modifier) => sum + modifier.valueMs, 0);
    if (
      baseDurationMs <= 0 ||
      finalDurationMs !== expected ||
      refreshBehavior !== "DURATION" ||
      refreshAttributes["refreshExtendsDuration"] ||
      refreshAttributes["auraDoesNotRefresh"] ||
      refreshAttributes["periodicEffectSubtypes"].length > 0
    ) {
      return invalid(
        "INCONSISTENT_DURATION",
        `aura '${label}' finalDurationMs ${String(finalDurationMs)} does not follow from base ${String(baseDurationMs)} and its modifiers under a DURATION refresh`,
      );
    }
  }
  return {
    atomName,
    abilityGameId,
    displayNameEn,
    baseDurationMs,
    durationModifiers: modifiers,
    finalDurationMs,
    maxStack,
    internalCooldownMs,
    refreshAttributes: {
      refreshExtendsDuration: refreshAttributes["refreshExtendsDuration"],
      auraDoesNotRefresh: refreshAttributes["auraDoesNotRefresh"],
      periodicEffectSubtypes: refreshAttributes["periodicEffectSubtypes"] as readonly number[],
    },
    refreshBehavior: model === "PERMANENT" ? "NONE" : "DURATION",
    remainsModel: model,
    review: {
      sourcePath: str(review, "sourcePath") ?? "",
      sourceSha256: str(review, "sourceSha256") ?? "",
      creation: str(review, "creation") ?? "",
      producers: str(review, "producers") ?? "",
      consumers: str(review, "consumers") ?? "",
    },
  };
}

export function validateBloodAuraDurationArtifact(value: unknown): BloodAuraDurationArtifactValidation {
  if (!isRecord(value)) return invalid("NOT_AN_OBJECT", "artifact is not an object");
  if (value["artifactVersion"] !== SUPPORTED_BLOOD_AURA_DURATION_ARTIFACT_VERSION) {
    return invalid("UNSUPPORTED_ARTIFACT_VERSION", `artifactVersion ${String(value["artifactVersion"])}`);
  }
  const datasetId = str(value, "datasetId");
  const artifactRevision = str(value, "artifactRevision");
  if (datasetId === null || artifactRevision === null) {
    return invalid("MALFORMED_PROVENANCE", "datasetId / artifactRevision missing");
  }
  const provenance = validateProvenance(value["provenance"]);
  if (provenance === null) return invalid("MALFORMED_PROVENANCE", "provenance is incomplete");
  if (provenance === "BAD_UNITS") {
    return invalid("UNSUPPORTED_DURATION_UNITS", "durationFieldUnits must be MILLISECONDS");
  }
  const rawAuras = value["auras"];
  if (!Array.isArray(rawAuras) || rawAuras.length === 0)
    return invalid("MALFORMED_AURAS", "auras is not a non-empty array");
  const auras: BloodAuraDurationIdentity[] = [];
  const atoms = new Set<string>();
  const ids = new Set<number>();
  for (const raw of rawAuras) {
    const aura = validateAura(raw);
    if ("ok" in aura) return aura;
    if (atoms.has(aura.atomName)) return invalid("DUPLICATE_ATOM", aura.atomName);
    if (ids.has(aura.abilityGameId)) return invalid("DUPLICATE_ABILITY_ID", String(aura.abilityGameId));
    atoms.add(aura.atomName);
    ids.add(aura.abilityGameId);
    auras.push(aura);
  }
  return { ok: true, artifact: { artifactVersion: 1, datasetId, artifactRevision, provenance, auras } };
}
